steps.text:
/*
	VIOC military_sites (configured copy, not part of the original mission).
	Called from Common\Init\Init_Location.sqf on every machine for each town.
	Airports, airfields, military bases, harbors, radio/radar sites and power plants get a bigger
	supply value: startSV and maxSV x VIOC_SITES_MULT_STRONG (2) or x VIOC_SITES_MULT_MEDIUM (1.5).
	Detection works on any map:
	  1) town name keywords (whole words), e.g. "Airport", "Military Base", "Le Port Harbor";
	  2) town centre within VIOC_SITES_AIRPORT_RANGE m of an airport of the current world
	     (CfgWorlds >> worldName: ilsPosition, ilsTaxiIn, ilsTaxiOff, and each SecondaryAirports class).
	Stores vioc_site_mult and vioc_site_maxSV0 on the town for the town spawn functions.
	Params:  [town logic, town name, startSV, maxSV]
	Returns: [startSV, maxSV, multiplier]
*/
params ["_town", "_name", "_startSV", "_maxSV"];

if (isNil "VIOC_SITES_MULT_STRONG") then {VIOC_SITES_MULT_STRONG = 2};       //--- airports, airfields, military bases, barracks
if (isNil "VIOC_SITES_MULT_MEDIUM") then {VIOC_SITES_MULT_MEDIUM = 1.5};     //--- harbors, ports, radio, radar, power plants, outposts
if (isNil "VIOC_SITES_AIRPORT_RANGE") then {VIOC_SITES_AIRPORT_RANGE = 750}; //--- metres to the runway threshold or a taxiway point

private _lname = toLower _name;
private _words = _lname splitString " -_.,;:()[]/'";
private _mult = 1;

//--- 1) Name keywords.
if (count (_words arrayIntersect ["airport", "airfield", "airbase", "aerodrome", "airstrip", "aeroport", "military", "base", "barracks", "garrison", "nwaf", "neaf"]) > 0 || {_lname find "air base" >= 0} || {_lname find "air station" >= 0}) then {
	_mult = VIOC_SITES_MULT_STRONG;
} else {
	if (count (_words arrayIntersect ["harbor", "harbour", "port", "docks", "pier", "radio", "radar", "outpost", "powerplant"]) > 0 || {_lname find "power plant" >= 0} || {_lname find "power station" >= 0}) then {
		_mult = VIOC_SITES_MULT_MEDIUM;
	};
};
if (_mult > VIOC_SITES_MULT_MEDIUM && {count (_words arrayIntersect ["ruined", "abandoned", "destroyed"]) > 0}) then {_mult = VIOC_SITES_MULT_MEDIUM};

//--- 2) Near an airport of this world (read from the terrain config, so it works on any map).
if (_mult < VIOC_SITES_MULT_STRONG) then {
	private _wcfg = configFile >> "CfgWorlds" >> worldName;
	private _airports = [_wcfg];
	if (isClass (_wcfg >> "SecondaryAirports")) then {_airports append ("true" configClasses (_wcfg >> "SecondaryAirports"))};
	private _tpos = getPos _town;
	private _near = false;
	{
		private _ap = _x;
		private _pts = [];
		private _ils = getArray (_ap >> "ilsPosition");
		if (count _ils > 1) then {_pts pushBack [_ils select 0, _ils select 1]};
		{
			private _flat = getArray (_ap >> _x);
			for "_i" from 0 to ((count _flat) - 2) step 2 do {_pts pushBack [_flat select _i, _flat select (_i + 1)]};
		} forEach ["ilsTaxiIn", "ilsTaxiOff"];
		{
			if (_x isEqualTypeAll 0 && {(_x select 0) > 0} && {(_x select 1) > 0} && {(_x select 0) < worldSize} && {(_x select 1) < worldSize} && {(_tpos distance2D _x) <= VIOC_SITES_AIRPORT_RANGE}) exitWith {_near = true};
		} forEach _pts;
		if (_near) exitWith {};
	} forEach _airports;
	if (_near) then {_mult = VIOC_SITES_MULT_STRONG};
};

_town setVariable ["vioc_site_mult", _mult];
_town setVariable ["vioc_site_maxSV0", _maxSV];

if (_mult > 1) then {
	_startSV = round (_startSV * _mult);
	_maxSV = round (_maxSV * _mult);
	diag_log format ["[VIOC military_sites] %1: x%2 -> startSV %3, maxSV %4", _name, _mult, _startSV, _maxSV];
};

[_startSV, _maxSV, _mult]

//--- VIOC military_sites: aeropuertos, aerodromos, bases, puertos, radio... mas SV y mas defensores (ver Common\Init\VIOC_military_sites.sqf)
if (isNil "VIOC_FNC_MilitarySite") then {VIOC_FNC_MilitarySite = compile preprocessFileLineNumbers "Common\Init\VIOC_military_sites.sqf"};
_vioc_site = [_town, _town_name, _town_startSV, _town_maxSV] call VIOC_FNC_MilitarySite;
_town_startSV = _vioc_site select 0;
_town_maxSV = _vioc_site select 1;

//--- VIOC military_sites: grupos extra en sitios militares aunque el maxSV pase el tope de 150 de arriba (se respeta el tope de 8 grupos)
private _vioc_m = _town getVariable ["vioc_site_mult", 1];
if (_vioc_m > 1) then {
	_totalGroups = (_totalGroups max (round (((_town getVariable ["vioc_site_maxSV0", _maxSV]) min 150) * CTI_TOWNS_RESISTANCE_GROUPS_RATIO * _vioc_m))) min 8;
};

//--- VIOC military_sites: grupos extra en sitios militares aunque el maxSV pase el tope de 120 de arriba (se respeta el tope de 8 grupos)
private _vioc_m = _town getVariable ["vioc_site_mult", 1];
if (_vioc_m > 1) then {
	_totalGroups = (_totalGroups max (round (((_town getVariable ["vioc_site_maxSV0", _maxSV]) min 120) * CTI_TOWNS_OCCUPATION_GROUPS_RATIO * _vioc_m))) min 8;
};
